import anthropic

def safe_stream_chat(client, history, user_input, system, model, max_tokens):
    try:
        return stream_chat(client, history, user_input, system, model, max_tokens)
    except anthropic.AuthenticationError:
        return "[오류] API 키가 유효하지 않습니다. .env 파일을 확인하세요."
    except anthropic._____:
        return "[오류] 요청 한도 초과. 잠시 후 다시 시도하세요."
    except anthropic.APIConnectionError:
        return "[오류] 네트워크 연결을 확인하세요."
